custom_fields.canvas:
[[[
  const dateTime = states["sensor.date_time"]?.state || "";
  const timePart = dateTime.split(", ")[1] || ""; const isDaytime = states["sun.sun"]?.state === "above_horizon";
  const [hourRaw, minuteRaw] = timePart.split(":");
  const hour = Number(hourRaw);
  const minute = minuteRaw || "00";
  const meridiem = hour >= 12 ? "PM" : "AM";
  const displayHour = hour % 12 || 12;
  const timeLabel = `${displayHour}:${minute}`;
  const weather = states["weather.forecast_housevoice_weather"];
  const weatherState = weather?.state || "";
  const weatherIcons = {"clear-night": "mdi:weather-night", sunny: "mdi:weather-sunny", partlycloudy: "mdi:weather-partly-cloudy", cloudy: "mdi:weather-cloudy", rainy: "mdi:weather-rainy", pouring: "mdi:weather-pouring", snowy: "mdi:weather-snowy", "snowy-rainy": "mdi:weather-snowy-rainy", lightning: "mdi:weather-lightning", "lightning-rainy": "mdi:weather-lightning-rainy", fog: "mdi:weather-fog", windy: "mdi:weather-windy", "windy-variant": "mdi:weather-windy-variant"};
  const weatherLabels = {"clear-night": "Clear Night", sunny: "Sunny", partlycloudy: "Partly Cloudy", cloudy: "Cloudy", rainy: "Rainy", pouring: "Pouring", snowy: "Snowy", "snowy-rainy": "Snowy Rain", lightning: "Lightning", "lightning-rainy": "Thunderstorms", fog: "Fog", windy: "Windy", "windy-variant": "Windy"};
  const weatherIcon = weatherIcons[weatherState] || "mdi:weather-cloudy";
  const weatherLabel = weatherLabels[weatherState] || "Unknown";
  const weatherTemperature = Number(weather?.attributes?.temperature);
  const weatherHumidity = Number(weather?.attributes?.humidity);
  const roomTemperature = Number(states["sensor.ikea_temp_sensor_temperature"]?.state); const roomHumidity = Number(states["sensor.ikea_temp_sensor_humidity"]?.state); const alarmState = states["alarm_control_panel.alarmo"]?.state || "unknown"; const alarmLabels = { disarmed: "Disarmed", armed_home: "Armed Home", armed_away: "Armed Away", armed_night: "Armed Night", triggered: "Triggered", pending: "Pending", arming: "Arming" }; const alarmColor = { disarmed: "#73e876", armed_home: "#ff8c00", armed_away: "#ff4444", armed_night: "#b966ff", triggered: "#ff0000", pending: "#ffaa00", arming: "#ffaa00" }[alarmState] || "#b966ff"; const alarmLabel = alarmLabels[alarmState] || "Unknown"; const openLocks = ["input_boolean.front_door_locked_mock", "input_boolean.back_door_locked_mock", "input_boolean.garage_entry_locked_mock"].filter(id => states[id]?.state !== "on").length; const locksLabel = Number.isFinite(openLocks) ? (openLocks > 0 ? openLocks + " Unlocked" : "All Locked") : "Unknown"; const garageClosed = states["input_boolean.garage_door_closed_mock"]?.state === "on"; const garageLabel = garageClosed ? "Closed" : "Open"; localStorage.setItem("housevoice_home", "/parents-room");

  return `
<div class="parents-canvas ${isDaytime ? "daytime" : "nighttime"} ">
  <div class="parents-brand">
    <img src="/local/housevoice/logo.svg?v=5" alt="HouseVoice">
    <div>
      <div class="brand-name">HOUSEVOICE</div>
      <div class="brand-room">PARENTS' ROOM</div>
    </div>
  </div>

  <div class="parents-weather">
    <span class="weather-time">${timeLabel}</span>
    <span class="weather-meridiem">${meridiem}</span>
    <ha-icon icon="${weatherIcon}"></ha-icon>
    <span class="weather-temp">${Number.isFinite(weatherTemperature) ? Math.round(weatherTemperature) : "--"}°</span>
  </div>

  <section class="glass-panel glance-panel">
    <h2>AT A GLANCE</h2>
    <div class="glance-row"><ha-icon icon="mdi:shield-star-outline"></ha-icon><span>Alarm</span><strong><span style="color:${alarmColor};">${alarmLabel}</span></strong></div>
    <div class="glance-row"><ha-icon icon="mdi:lock-outline"></ha-icon><span>Locks</span><strong><span style="color:${openLocks > 0 ? "#ff5a52" : "#73e876"};">${locksLabel}</span></strong></div>
    <div class="glance-row"><ha-icon icon="mdi:garage"></ha-icon><span>Garage</span><strong><span style="color:${garageClosed ? "#73e876" : "#ff5a52"};">${garageLabel}</span></strong></div>
    <div class="glance-row"><ha-icon icon="mdi:thermometer"></ha-icon><span>Indoor Temp</span><strong class="neutral">${Number.isFinite(roomTemperature) ? Math.round(roomTemperature) : "--"}°</strong></div>
    <div class="glance-row"><ha-icon icon="mdi:water-outline"></ha-icon><span>Humidity</span><strong class="neutral">${Number.isFinite(roomHumidity) ? Math.round(roomHumidity) : "--"}%</strong></div>
  </section>

  <div class="center-message">
    <div class="greeting">Good Evening</div>
    <div class="greeting-subtitle">Everything looks good.</div>
  </div>

  <section class="glass-panel quick-panel">
    <h2>QUICK ACTIONS</h2>
    <div class="quick-action light-action"><ha-icon icon="mdi:lightbulb-outline"></ha-icon><div><b>BEDROOM LIGHT</b><span>Off</span></div></div>
    <div class="quick-action music-action"><ha-icon icon="mdi:music-note-outline"></ha-icon><div><b>MUSIC</b><span>Not Playing</span></div></div>
    <div class="quick-action intercom-action"><ha-icon icon="mdi:cellphone-basic"></ha-icon><div><b>INTERCOM</b><span>Choose Room</span></div></div>
  </section>

  <nav class="parents-nav">
    <a class="parents-nav-item alarm-nav" href="/control-panels/alarm-control"><ha-icon icon="mdi:shield-star-outline"></ha-icon><span>ALARM</span></a>
    <a class="parents-nav-item lights-nav" href="/my-floorplan/lights-control"><ha-icon icon="mdi:lightbulb-outline"></ha-icon><span>LIGHTS</span></a>
    <a class="parents-nav-item locks-nav" href="/my-floorplan/locks-control"><ha-icon icon="mdi:lock-outline"></ha-icon><span>LOCKS</span></a>
    <a class="parents-nav-item cameras-nav" href="/my-floorplan/cameras-control"><ha-icon icon="mdi:cctv"></ha-icon><span>CAMERAS</span></a>
    <a class="parents-nav-item temp-nav" href="/my-floorplan/thermostat-control"><ha-icon icon="mdi:thermometer"></ha-icon><span>TEMP</span></a>
  </nav>
</div>
`;
]]]

cards.extra_styles:
:host {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.parents-canvas {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(100vw, calc(100dvh * 1.6));
  height: min(100dvh, calc(100vw / 1.6));
  transform: translate(-50%, -50%);
  overflow: hidden;
  color: #f4f7fa;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background:
    linear-gradient(to bottom, rgba(3, 20, 52, .72) 0%, rgba(4, 23, 57, .58) 22%, rgba(1, 5, 14, .04) 48%, rgba(1, 5, 14, .20) 100%),
    url('/local/housevoice/assets/references/banff%20at%20night.png') center center / cover no-repeat;
}

.parents-canvas.daytime {
  background-image: linear-gradient(to bottom, rgba(228, 241, 255, .22) 0%, rgba(255, 250, 232, .08) 45%, rgba(1, 5, 14, .12) 100%), url("/local/housevoice/assets/references/lake%20louise%20daytime.png");
}

.parents-brand {
  position: absolute;
  left: 4.7%;
  top: 4.2%;
  display: flex;
  align-items: center;
  gap: 14px;
}

.parents-brand img {
  width: 112px;
  height: 68px;
  object-fit: contain;
}

.brand-name {
  font-size: 31px;
  font-weight: 400;
  letter-spacing: 9px;
  white-space: nowrap;
}

.brand-room {
  margin-top: 7px;
  color: #53b9ff;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: 7px;
  white-space: nowrap;
}

.parents-weather {
  position: absolute;
  top: 5.2%;
  right: 4.6%;
  display: flex;
  align-items: baseline;
  gap: 7px;
  white-space: nowrap;
}

.parents-weather ha-icon {
  align-self: center;
  margin-left: 17px;
  color: #e9eff5;
  --mdc-icon-size: 35px;
}

.weather-time {
  font-size: 52px;
  font-weight: 300;
  line-height: 1;
}

.weather-meridiem {
  font-size: 21px;
  font-weight: 300;
}

.weather-temp {
  font-size: 39px;
  font-weight: 300;
}

.glass-panel {
  position: absolute;
  box-sizing: border-box;
  width: 24%;
  height: 46.5%;
  padding: 30px 30px;
  border: 1px solid rgba(120, 170, 205, .28);
  border-radius: 21px;
  background: linear-gradient(145deg, rgba(7, 24, 42, .84), rgba(3, 15, 29, .76));
  box-shadow: 0 12px 30px rgba(0, 0, 0, .24), inset 0 1px 0 rgba(255, 255, 255, .04);
  backdrop-filter: blur(10px);
}

.glance-panel {
  left: 5.2%;
  top: 21.3%;
}

.quick-panel {
  right: 5.2%;
  top: 21.3%;
  padding: 30px 19px 20px;
}

h2 {
  margin: 0 0 18px;
  color: #f1f5f8;
  font-size: 18px;
  font-weight: 400;
  letter-spacing: 3px;
}

.glance-row {
  display: grid;
  grid-template-columns: 30px 1fr 108px;
  align-items: center;
  height: 19.2%;
  border-bottom: 1px solid rgba(137, 169, 199, .165);
  column-gap: 12px;
  white-space: nowrap;
}

.glance-row:last-child {
  border-bottom: 0;
}

.glance-row ha-icon {
  color: #f0f5f8;
  --mdc-icon-size: 30px;
}

.glance-row span {
  font-size: 18px;
  color: rgba(244, 247, 250, .92);
}

.glance-row strong {
  color: #7ee87a;
  font-size: 18px;
  font-weight: 400;
  justify-self: end;
}

.glance-row strong.neutral {
  color: #f0f3f5;
}

.center-message {
  position: absolute;
  left: 50%;
  top: calc(41.5% - 101px);
  transform: translate(-50%, -50%);
  text-align: center;
  white-space: nowrap;
}

.greeting {
  font-size: 37px;
  font-weight: 300;
}

.greeting-subtitle {
  margin-top: 12px;
  color: rgba(235, 242, 250, .82);
  font-size: 18px;
  font-weight: 300;
}

.quick-action {
  display: flex;
  align-items: center;
  gap: 9px;
  box-sizing: border-box;
  height: 84px;
  margin-bottom: 12px;
  padding: 0 14px;
  border: 1px solid rgba(120, 165, 205, .35);
  border-radius: 17px;
  background: linear-gradient(135deg, rgba(17, 32, 50, .82), rgba(5, 17, 31, .76));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .045), 0 5px 15px rgba(0, 0, 0, .18);
}

.quick-action:last-child {
  margin-bottom: 0;
}

.quick-action ha-icon {
  --mdc-icon-size: 40px;
  flex: 0 0 60px;
}

.quick-action div {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.quick-action b {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: .5px;
}

.quick-action span {
  color: rgba(239, 232, 225, .78);
  font-size: 16px;
}

.light-action {
  border-color: rgba(255, 207, 111, .42);
}

.light-action ha-icon {
  color: #ffd16e;
}

.music-action {
  border-color: rgba(173, 126, 237, .5);
}

.music-action ha-icon {
  color: #c795ff;
}

.intercom-action {
  border-color: rgba(83, 185, 255, .45);
}

.intercom-action ha-icon,
.intercom-action b {
  color: #73caff;
}

.parents-nav {
  position: absolute;
  left: 5.2%;
  right: 5.2%;
  bottom: 6.5%;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  height: 14.3%;
  box-sizing: border-box;
  border: 1px solid rgba(115, 160, 195, .28);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .28), inset 0 1px 0 rgba(255, 255, 255, .045);
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(6, 22, 38, .90), rgba(2, 13, 25, .94));
  backdrop-filter: blur(10px);
}

.parents-nav-item {
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  border-right: 1px solid rgba(150, 185, 215, .16);
  font-size: 18px;
  letter-spacing: 1px;
}

.parents-nav-item span {
  transform: translateY(-18px);
}

.parents-nav-item:last-child {
  border-right: 0;
}

.parents-nav-item ha-icon {
  --mdc-icon-size: 45px;
  transform: translateY(6px);
}

.alarm-nav ha-icon {
  color: #ff5a52;
}

.temp-nav ha-icon {
  color: #73caff;
}

.lights-nav ha-icon {
  color: #ffd16e;
}

.locks-nav ha-icon {
  color: #82e66f;
}

.cameras-nav ha-icon {
  color: #b966ff;
}


.music-action ha-icon,
.intercom-action ha-icon {
  margin-left: 0;
  margin-right: 0;
}


.music-action ha-icon,
.intercom-action ha-icon {
  margin: 0 !important;
  position: relative !important;
  left: 0 !important;
}




.quick-action {
  display: grid;
  grid-template-columns: 60px 1fr;
  column-gap: 9px;
}

.quick-action ha-icon {
  width: 60px;
  margin: 0 !important;
  position: static !important;
  left: auto !important;
  transform: none !important;
  justify-self: center;
}

.quick-action > div {
  min-width: 0;
  margin: 0;
}


.quick-action {
  position: relative;
}

.quick-action > div {
  position: absolute;
  left: 88px;
  top: 50%;
  transform: translateY(-50%);
}


.quick-action > div {
  left: 88px !important;
  width: 190px;
  align-items: flex-start !important;
  text-align: left !important;
}

.quick-action > div b,
.quick-action > div span {
  display: block;
  width: 100%;
  text-align: left;
}

.parents-canvas.daytime .parents-brand,
.parents-canvas.daytime .parents-weather,
.parents-canvas.daytime .center-message {
  color: #062b55;
}

.parents-canvas.daytime .brand-room {
  color: #0a5a8f;
}

.parents-canvas.daytime .parents-weather ha-icon,
.parents-canvas.daytime .weather-temp,
.parents-canvas.daytime .weather-time,
.parents-canvas.daytime .weather-meridiem {
  color: #062b55;
}

.parents-canvas.daytime .greeting-subtitle {
  color: rgba(6, 43, 85, .82);
}
